#!/usr/bin/env bash
S4=/tmp/claude-1000/-home-claude-cto/b1caac4c-9b75-4393-9260-1c72f906f86b/scratchpad; SO=/tmp/claude-1000/-home-claude-cto/25cbd82c-ea4e-46bc-9ee6-3c52fc5dcc1f/scratchpad; W=$SO/hdr/SCRIP; H=$SO/hdr/harness/scripts; cd $W || exit 2
echo "== 0 pristine  $(date +%T)"; CCACHE_DISABLE=1 S4E_NO_BUILD_CACHE=1 make -j8 pristine > $S4/s7-pristine.log 2>&1; echo "pristine rc=$? compiles=$(grep -c -- ' -c ' $S4/s7-pristine.log) errors=$(grep -c ' error' $S4/s7-pristine.log)"
echo "== 1 R5"; WO=/tmp/si_objs$(printf %s "$W" | tr / -); bash $H/util_objects_identical_stripped.sh --no-comdat $S4/parent-objs-7/obj $WO $S4/parent-objs-7/out $W/out > $S4/r5-7.log 2>&1; echo "R5 rc=$? :: $(grep '^objects=' $S4/r5-7.log | cut -c1-300)"; grep -E '^(DIFF|ONLY)' $S4/r5-7.log | head -8 | cut -c1-200
echo "== 2 the arms and the after table"; python3 -I $H/util_header_fanin.py --root $W --ratchet all 2>/dev/null | grep -E 'RAISED|^arm' | cut -c1-120; python3 -I $S4/after_table.py $W $H 2>&1 | cut -c1-600
echo "== 3 style"; files=$(git diff --name-only HEAD -- src | while read f; do [ -f "$f" ] && echo "$f"; done); python3 ../harness/scripts/util_reflow_200.py --check $files 2>&1 | tail -1 | cut -c1-160; python3 ../harness/scripts/strip_comments.py --check $files 2>&1 | tail -1 | cut -c1-160
echo "== 4 smokes  $(date +%T)"; for l in snobol4 snocone rebus icon prolog pascal raku scrip_all_modes; do S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash ../harness/scripts/test_smoke_$l.sh > $S4/smoke7-$l.log 2>&1; echo "SMOKE $l rc=$?"; done
echo "== 5 gates  $(date +%T)"; for g in test_gate_no_header_reaches_more_units_than_its_users.sh test_gate_dyn_caps_ratchet.sh test_gate_pl_trail_mechanism.sh test_gate_stage2_isolation.sh test_gate_planner_six_passes_read_no_emitter_state.sh test_gate_gc_map_table_present_in_both_media.sh; do t0=$(date +%s); S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash $H/$g > $S4/gate7-$g.log 2>&1; echo "GATE $g rc=$? $(( $(date +%s) - t0 ))s :: $(grep -E 'GATE (OK|PASS|FAIL|RED|GREEN|UNPROVEN)|⛔|REFUSE|summary' $S4/gate7-$g.log | tail -1 | cut -c1-110)"; done
grep -E '^  (ok|FAIL) +[0-9]+' $S4/gate7-test_gate_dyn_caps_ratchet.sh.log | cut -c1-60 | tr '\n' ';'; echo
echo "== 6 the step-7 DONE-WHEN against this tree"; sed -n 's/^DONE-WHEN: //p' /home/resources/postoffice/tasks/headers-step-7-*.task.md > $S4/dw7.sh; S4E_HOME=$SO/hdr bash $S4/dw7.sh 2>&1 | tail -1 | cut -c1-160
echo "7 PROOF DONE $(date +%T)"
